{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Absolute oral bioavailability of lefamulin, a structurally related diterpenoid antibiotic, was 21.08% (90% CI 19.24–23.09%) in patients, meeting the ≥20% threshold and supporting high bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "A second absolute bioavailability study of lefamulin reported 25.8% for a 600 mg immediate-release tablet versus IV in healthy subjects, directly supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Tacrolimus, a complex macrocyclic lactone with the highest transfer score, has mean oral bioavailability 25±10% in liver transplant recipients, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C65"],
      "claim": "BMS-275183, a complex diterpenoid-like oral taxane, has 24% oral bioavailability in humans, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Amphotericin B has negligible oral bioavailability due to poor membrane permeability, low solubility, and instability; this contradictory evidence is mechanistically less transferable to the smaller, lipophilic polycyclic lactone query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High-transfer experimental evidence from structurally related complex diterpenoid/macrocyclic lactones (lefamulin, tacrolimus, BMS-275183) consistently shows absolute oral bioavailability around 20–26%, meeting the ≥20% threshold. The low-bioavailability amphotericin B evidence reflects size/polarity/instability liabilities not shared by the query. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the exact query molecule.",
    "Several supportive analogues are borderline near the 20% threshold.",
    "Amphotericin B has a high transfer score but its poor-absorption mechanism may not apply to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

